from pathlib import Path
lines=Path('/app/dataset/genealogy_trees.txt').read_text().splitlines()
H=len(lines); W=max(len(l) for l in lines)
grid=[l.ljust(W) for l in lines]
HSET=set('-~ ')
VSET=set('|│')
boxes=[]
seen=set()
for y in range(H):
    row=grid[y]
    pluses=[i for i,ch in enumerate(row) if ch=='+']
    for a_idx,x0 in enumerate(pluses):
        for x1 in pluses[a_idx+1:]:
            if x1-x0 < 3 or x1-x0>40:
                continue
            if any(ch not in HSET for ch in row[x0+1:x1]):
                continue
            # height 2..8 (top+bottom at least one interior row)
            for y2 in range(y+2, min(H, y+9)):
                if grid[y2][x0] != '+' or grid[y2][x1] != '+':
                    continue
                if any(ch not in HSET for ch in grid[y2][x0+1:x1]):
                    continue
                ok=True
                has_text=False
                for yy in range(y+1,y2):
                    if grid[yy][x0] not in VSET or grid[yy][x1] not in VSET:
                        ok=False; break
                    inner=grid[yy][x0+1:x1]
                    if any(ch.isalpha() or ch.isdigit() for ch in inner):
                        has_text=True
                if not ok or not has_text:
                    continue
                key=(x0,y,x1,y2)
                boxes.append(key)
                break
# dedupe nested? sort
print('boxes',len(boxes))
for b in boxes[:20]:
    x0,y0,x1,y1=b
    texts=[]
    for yy in range(y0+1,y1):
        t=grid[yy][x0+1:x1].rstrip()
        if t.strip():
            texts.append(' '.join(t.split()))
    name=' '.join(texts)
    print(b,name)
