python - <<'PY'
from pathlib import Path
from collections import deque,defaultdict
lines=Path('/app/dataset/genealogy_trees.txt').read_text().splitlines()
H=len(lines); W=max(len(l) for l in lines)
grid=[list(l.ljust(W)) for l in lines]
HSET=set('-~ ')
VSET=set('|│')
# relaxed box detection
boxes=[]
for y in range(H):
    row=''.join(grid[y])
    pluses=[i for i,ch in enumerate(row) if ch=='+']
    for a_idx,x0 in enumerate(pluses):
        for x1 in pluses[a_idx+1:]:
            if x1-x0 < 3 or x1-x0>40:
                continue
            if any(ch not in HSET for ch in row[x0+1:x1]):
                continue
            for y2 in range(y+2, min(H, y+10)):
                if grid[y2][x0] != '+' or grid[y2][x1] != '+':
                    continue
                if any(ch not in HSET for ch in grid[y2][x0+1:x1]):
                    continue
                texts=[]
                left_ok=right_ok=False
                ok=True
                for yy in range(y+1,y2):
                    lch=grid[yy][x0]
                    rch=grid[yy][x1]
                    if lch in VSET: left_ok=True
                    if rch in VSET: right_ok=True
                    if lch not in VSET and rch not in VSET:
                        ok=False; break
                    inner=''.join(grid[yy][x0+1:x1])
                    # allow letters/spaces only-ish; strip multiple spaces
                    if '+' in inner:
                        ok=False; break
                    t=' '.join(inner.split())
                    if t:
                        texts.append(t)
                if not ok or not texts or not (left_ok or right_ok):
                    continue
                name=' '.join(texts)
                # filter names: mostly letters/spaces and length reasonable
                if not any(c.isalpha() for c in name):
                    continue
                boxes.append({'name':name,'x0':x0,'x1':x1,'y0':y,'y1':y2})
                break
# dedupe overlapping identical coords with longer name maybe
uniq={}
for b in boxes:
    key=(b['x0'],b['x1'],b['y0'],b['y1'])
    if key not in uniq or len(b['name'])>len(uniq[key]['name']):
        uniq[key]=b
boxes=list(uniq.values())
# mask boxes
conn_chars=set('+-~|/\\│')
mask=[row[:] for row in grid]
for b in boxes:
    for y in range(b['y0'],b['y1']+1):
        for x in range(b['x0'],b['x1']+1):
            mask[y][x]=' '
# components on mask
comp=[[-1]*W for _ in range(H)]
comps=[]
for y in range(H):
    for x in range(W):
        if mask[y][x] in conn_chars and comp[y][x]==-1:
            cid=len(comps)
            q=deque([(y,x)])
            comp[y][x]=cid
            cells=[]
            while q:
                cy,cx=q.popleft()
                cells.append((cy,cx))
                for dy in (-1,0,1):
                    for dx in (-1,0,1):
                        if dy==0 and dx==0: continue
                        ny,nx=cy+dy,cx+dx
                        if 0<=ny<H and 0<=nx<W and comp[ny][nx]==-1 and mask[ny][nx] in conn_chars:
                            comp[ny][nx]=cid
                            q.append((ny,nx))
            comps.append(cells)
# find Dawid box
b=next(bb for bb in boxes if bb['name']=='Dawid Majtyka')
print('Dawid',b)
# top neighborhood comps
cids=set()
for y in range(max(0,b['y0']-1), b['y0']+1):
    for x in range(max(0,b['x0']-1), min(W,b['x1']+2)):
        cid=comp[y][x]
        if cid!=-1: cids.add(cid)
print('top cids',cids)
for cid in cids:
    ys=[y for y,x in comps[cid]]; xs=[x for y,x in comps[cid]]
    print('cid',cid,'bbox',min(xs),min(ys),max(xs),max(ys),'size',len(comps[cid]))
    # nearby boxes touching this comp within 1 cell
    touch=[]
    cellset=set(comps[cid])
    for bb in boxes:
        touched=False
        for y in range(bb['y0'],bb['y1']+1):
            for x in range(bb['x0'],bb['x1']+1):
                for dy in (-1,0,1):
                    for dx in (-1,0,1):
                        if (y+dy,x+dx) in cellset:
                            touched=True; break
                    if touched: break
                if touched: break
            if touched: break
        if touched:
            touch.append(bb['name'])
    print('touch count',len(touch))
    print(touch[:20])
PY

